// ============================================================================
//
// Generate ID_MESSAGE (token for header Message-ID).
// Arguments
//      AI_SERVER (input): mail server.
//      AO_ID_MESSAGE (output): Message ID.
//
// Return M4_SUCCESS if successfull; M4_ERROR otherwise
//
// ============================================================================

AO_ID_MESSAGE = NullValue()

AO_ID_MESSAGE = "META400-" + GetUniqueID() + "@" + AI_SERVER

return M4_SUCCESS

// ============================================================================
//
// Get errors for mail sending.
// Arguments
//      AI_FIRST_ERROR (input number): First error to add
//      AI_LAST_ERROR (input number): Last error to add
//      AO_ERRORS (output error string): error string
//
// Return M4_SUCCESS if successfull; M4_ERROR otherwise
//
// ============================================================================

AO_ERRORS = NullValue()

text = ""
for i = AI_FIRST_ERROR to AI_LAST_ERROR
    
    errorType = NullValue()
    errorModule = NullValue()
    errorSubmodule = NullValue()
    errorCode = NullValue()
    errorText = NullValue()
    
    GetLog( i, errorType, errorModule, errorSubmodule, errorCode, errorText )
    
    if text <> "" then
        text = text + Chr( M4_CR )
    endif
    
    if errorType = M4_ERRORLOG then
        text = text + "Error "
    else
        if errorType = M4_WARNINGLOG then
            text = text + "Warnig "
        else
            text = text + "Information "
        endif
    endif
    
    text = text + ToString( errorModule * 16777216 + errorSubmodule* 65536 + errorCode, 0 ) + " "
    text = text + Replace( GetErrorString( errorModule, errorSubmodule, errorCode, errorText ), Chr( M4_CR ), " " )
next

AO_ERRORS = text

