// -----------------------------------------------------------------------------
//  _CACHE_ITEM_GET
//
//  Retrieves from the cache an application parameter value for a given context.
//
//  AI_APPLICATION: Application parameter application.
//  AI_SECTION: Application parameter section.
//  AI_KEY: Application parameter key.
//  AI_USER: User context.
//  AI_LANGUAGE: Language context.
//  AI_ORGANIZATION: Organization context.
//  AI_ROLE: Role context.
//  AO_FOUND: Output boolean. Found or not in the cache store.
//
//  Returns: M4_SUCCESS/M4_ERROR
// -----------------------------------------------------------------------------

If _CACHE_ENABLED() = M4_FALSE Then
    AO_FOUND = M4_FALSE
    Return M4_SUCCESS
EndIf

// Trace.
bTrace = _CACHE_TRACE()
sSep = Chr(M4_TAB)
If bTrace = M4_TRUE Then
    sTraceFile = SCH_SESSION!APP_PARAM_CACHE.CC_TRACE_FILE
    ConcatFile( sTraceFile, toString(todayNowGMT()), 0 )
endif

// Searchs in the cache.
iPos = SCH_SESSION!APP_PARAM_CACHE.FindRegister( "CK_APPLICATION", AI_APPLICATION, M4_EQUAL, "CK_SECTION", AI_SECTION, M4_EQUAL, "CK_KEY", AI_KEY, M4_EQUAL, "CK_USER", AI_USER, M4_EQUAL, "CK_LANGUAGE", AI_LANGUAGE, M4_EQUAL, "CK_ORGANIZATION", AI_ORGANIZATION, M4_EQUAL, "CK_ROLE", AI_ROLE, M4_EQUAL )

If iPos <> -1 Then
    SCH_SESSION!APP_PARAM_CACHE.MoveTo( iPos )

    If SCH_SESSION!APP_PARAM_CACHE.CV_HAS_VALUE = M4_TRUE Then
        // Copies it to the results node.
        FINAL_RETURN_40.AddRegister()
    
        FINAL_RETURN_40.ID_APLICATION  = SCH_SESSION!APP_PARAM_CACHE.CK_APPLICATION
        FINAL_RETURN_40.ID_SECTION     = SCH_SESSION!APP_PARAM_CACHE.CK_SECTION
        FINAL_RETURN_40.ID_KEY         = SCH_SESSION!APP_PARAM_CACHE.CK_KEY
    
        FINAL_RETURN_40.ID_CONCEPT     = SCH_SESSION!APP_PARAM_CACHE.CV_CONCEPT
        FINAL_RETURN_40.VALUE_CONCEPT  = SCH_SESSION!APP_PARAM_CACHE.CV_CONCEPT_VAL
        FINAL_RETURN_40.TYPE_VALUE     = SCH_SESSION!APP_PARAM_CACHE.CV_TYPE
        FINAL_RETURN_40.PATH_REG       = ""
        FINAL_RETURN_40.DT_LAST_UPDATE = SCH_SESSION!APP_PARAM_CACHE.CV_LAST_UPDATE
        FINAL_RETURN_40.ID_T3          = SCH_SESSION!APP_PARAM_CACHE.CV_T3
        FINAL_RETURN_40.IS_INTERNAL    = SCH_SESSION!APP_PARAM_CACHE.CV_INTERNAL
        FINAL_RETURN_40.APP_VALUE      = SCH_SESSION!APP_PARAM_CACHE.CV_VALUE
    EndIf
    
    AO_FOUND = M4_TRUE

    // Trace.
    If bTrace = M4_TRUE Then
        ConcatFile( sTraceFile, sSep + toString(SCH_SESSION!APP_PARAM_CACHE.CI_STORE, 0) + sSep + "get" + sSep + AI_APPLICATION + sSep + AI_SECTION + sSep + AI_KEY + sSep + AI_USER + sSep + AI_ROLE + sSep + AI_ORGANIZATION + sSep + tostring(AI_LANGUAGE,0) + sSep, 0 )
        ConcatFile( sTraceFile, toString(iPos,0) + sSep + toString( SCH_SESSION!APP_PARAM_CACHE.Count(),0 ) + sSep + sSep, 0 )
        If SCH_SESSION!APP_PARAM_CACHE.CV_HAS_VALUE = M4_TRUE Then
            ConcatFile( sTraceFile, FINAL_RETURN_40.ID_CONCEPT + sSep + FINAL_RETURN_40.VALUE_CONCEPT + sSep + UTILS.STR_TO_CSV(FINAL_RETURN_40.APP_VALUE), 0 )
        Else
            ConcatFile( sTraceFile, sSep + sSep, 0 )
        EndIf
        ConcatFile( sTraceFile, sSep + toString(SCH_SESSION!APP_PARAM_CACHE.CI_SIZE,0) + sSep + toString(SCH_SESSION!APP_PARAM_CACHE.CI_TOTAL_SIZE,0), 1)
    EndIf
Else
    AO_FOUND = M4_FALSE

    // Trace.
    If bTrace = M4_TRUE Then
        ConcatFile( sTraceFile, sSep + "" + sSep + "get" + sSep + AI_APPLICATION + sSep + AI_SECTION + sSep + AI_KEY + sSep + AI_USER + sSep + AI_ROLE + sSep + AI_ORGANIZATION + sSep + tostring(AI_LANGUAGE,0) + sSep, 0 )
        ConcatFile( sTraceFile, sSep + toString( SCH_SESSION!APP_PARAM_CACHE.Count(),0 ) + sSep + sSep, 0 )
        ConcatFile( sTraceFile, sSep + sSep + sSep, 0 )
        ConcatFile( sTraceFile, sSep + toString(SCH_SESSION!APP_PARAM_CACHE.CI_TOTAL_SIZE,0), 1)
    EndIf
EndIf


Return M4_SUCCESS

// -----------------------------------------------------------------------------
//  _CACHE_ITEM_INSERT
//
//  Inserts in the cache an application parameter value for a given context.
//
//  AI_APPLICATION: Application parameter application.
//  AI_SECTION: Application parameter section.
//  AI_KEY: Application parameter key.
//  AI_USER: User context.
//  AI_LANGUAGE: Language context.
//  AI_ORGANIZATION: Organization context.
//  AI_ROLE: Role context.
//  AI_GROUP: Multiple insertion group string.
//  AI_HAS_VALUE: Application parameter has value or not.
//  AI_STORE: Value's store.
//
//  Returns: M4_SUCCESS/M4_ERROR
// -----------------------------------------------------------------------------

If _CACHE_ENABLED() = M4_FALSE Then
    Return M4_SUCCESS
EndIf

// Searchs in the cache.
iPos = SCH_SESSION!APP_PARAM_CACHE.FindRegister( "CK_APPLICATION", AI_APPLICATION, M4_EQUAL, "CK_SECTION", AI_SECTION, M4_EQUAL, "CK_KEY", AI_KEY, M4_EQUAL, "CK_USER", AI_USER, M4_EQUAL, "CK_LANGUAGE", AI_LANGUAGE, M4_EQUAL, "CK_ORGANIZATION", AI_ORGANIZATION, M4_EQUAL, "CK_ROLE", AI_ROLE, M4_EQUAL )

If iPos = -1 Then
    // Adds the item to the cache store.
    SCH_SESSION!APP_PARAM_CACHE.AddRegister()

    SCH_SESSION!APP_PARAM_CACHE.CK_APPLICATION  = AI_APPLICATION
    SCH_SESSION!APP_PARAM_CACHE.CK_SECTION      = AI_SECTION
    SCH_SESSION!APP_PARAM_CACHE.CK_KEY          = AI_KEY
    SCH_SESSION!APP_PARAM_CACHE.CK_USER         = AI_USER
    SCH_SESSION!APP_PARAM_CACHE.CK_LANGUAGE     = AI_LANGUAGE
    SCH_SESSION!APP_PARAM_CACHE.CK_ORGANIZATION = AI_ORGANIZATION
    SCH_SESSION!APP_PARAM_CACHE.CK_ROLE         = AI_ROLE
    SCH_SESSION!APP_PARAM_CACHE.CI_STORE        = AI_STORE
        
    If AI_HAS_VALUE = M4_TRUE Then
        SCH_SESSION!APP_PARAM_CACHE.CV_CONCEPT      = FINAL_RETURN_40.ID_CONCEPT
        SCH_SESSION!APP_PARAM_CACHE.CV_CONCEPT_VAL  = FINAL_RETURN_40.VALUE_CONCEPT
        SCH_SESSION!APP_PARAM_CACHE.CV_TYPE         = FINAL_RETURN_40.TYPE_VALUE
        SCH_SESSION!APP_PARAM_CACHE.CV_LAST_UPDATE  = FINAL_RETURN_40.DT_LAST_UPDATE
        SCH_SESSION!APP_PARAM_CACHE.CV_T3           = FINAL_RETURN_40.ID_T3
        SCH_SESSION!APP_PARAM_CACHE.CV_INTERNAL     = FINAL_RETURN_40.IS_INTERNAL
        SCH_SESSION!APP_PARAM_CACHE.CV_VALUE        = FINAL_RETURN_40.APP_VALUE
    EndIf
    
    SCH_SESSION!APP_PARAM_CACHE.CV_HAS_VALUE = AI_HAS_VALUE
    
    // Trace.
    If _CACHE_TRACE() = M4_TRUE Then
        sTraceFile = SCH_SESSION!APP_PARAM_CACHE.CC_TRACE_FILE
        sSep = Chr(M4_TAB)
        iPos = SCH_SESSION!APP_PARAM_CACHE.Count()
        
        SCH_SESSION!APP_PARAM_CACHE.SIZE_CHANGED("NEW")

        ConcatFile(sTraceFile, toString(todayNowGMT()) + sSep + toString(AI_STORE, 0) + sSep + "insert" + sSep + AI_APPLICATION + sSep + AI_SECTION + sSep + AI_KEY + sSep + AI_USER + sSep + AI_ROLE + sSep + AI_ORGANIZATION + sSep + tostring(AI_LANGUAGE,0) + sSep, 0)
        ConcatFile(sTraceFile, toString(iPos - 1,0) + sSep + toString(iPos,0) + sSep + AI_GROUP + sSep, 0)
        If AI_HAS_VALUE = M4_TRUE Then
            ConcatFile(sTraceFile, FINAL_RETURN_40.ID_CONCEPT + sSep + FINAL_RETURN_40.VALUE_CONCEPT + sSep + UTILS.STR_TO_CSV(FINAL_RETURN_40.APP_VALUE), 0)
        Else
            ConcatFile(sTraceFile, sSep + sSep, 0)
        EndIf
        ConcatFile(sTraceFile, sSep + toString(SCH_SESSION!APP_PARAM_CACHE.CI_SIZE,0) + sSep + toString(SCH_SESSION!APP_PARAM_CACHE.CI_TOTAL_SIZE,0), 1)
    EndIf
EndIf


Return M4_SUCCESS

// -----------------------------------------------------------------------------
//  _CACHE_ITEM_UPDATE
//
//  Updates the cached value of an application parameter in a given scope.
//
//  AI_APPLICATION: Application parameter application.
//  AI_SECTION: Application parameter section.
//  AI_KEY: Application parameter key.
//  AI_CONCEPT: Scope Id.
//  AI_VALUE_CONCEPT: Scope value.
//  AI_APP_VALUE: New application parameter value.
//
//  Returns: M4_SUCCESS/M4_ERROR
// -----------------------------------------------------------------------------

If _CACHE_ENABLED() = M4_FALSE Then
    Return M4_SUCCESS
EndIf

// Trace.
bTrace = _CACHE_TRACE()
If bTrace = M4_TRUE Then
    sTraceFile = SCH_SESSION!APP_PARAM_CACHE.CC_TRACE_FILE
    sSep = Chr(M4_TAB)
    iCount = SCH_SESSION!APP_PARAM_CACHE.Count()
EndIf

// Updates all cached values solved to that scope. 
// Several contexts (e.g. user contexts) could have the same value coming from a lower level (e.g. organization)
iPos = -1

Do
    // Searchs in the cache.
    iPos = SCH_SESSION!APP_PARAM_CACHE.FindRegister( "CK_APPLICATION", AI_APPLICATION, M4_EQUAL, "CK_SECTION", AI_SECTION, M4_EQUAL, "CK_KEY", AI_KEY, M4_EQUAL, "CV_CONCEPT", AI_CONCEPT, M4_EQUAL, "CV_CONCEPT_VAL", AI_VALUE_CONCEPT, M4_EQUAL, iPos + 1 )
    
    If iPos <> -1 Then
        // Updates the cache item.
        SCH_SESSION!APP_PARAM_CACHE.Moveto( iPos )
    
        SCH_SESSION!APP_PARAM_CACHE.CV_VALUE = AI_APP_VALUE

        // Trace.        
        If bTrace = M4_TRUE Then
            SCH_SESSION!APP_PARAM_CACHE.SIZE_CHANGED("UPDATED")
            
            ConcatFile(sTraceFile, toString(todayNowGMT()) + sSep + toString(SCH_SESSION!APP_PARAM_CACHE.CI_STORE, 0) + sSep + "update" + sSep + AI_APPLICATION + sSep + AI_SECTION + sSep + AI_KEY + sSep + sSep  + sSep + sSep + sSep, 0)
            ConcatFile(sTraceFile, toString(iPos, 0) + sSep + toString(iCount,0) + sSep + sSep, 0)
            ConcatFile(sTraceFile, AI_CONCEPT + sSep + AI_VALUE_CONCEPT + sSep + UTILS.STR_TO_CSV(AI_APP_VALUE), 0)
            ConcatFile(sTraceFile, sSep + toString(SCH_SESSION!APP_PARAM_CACHE.CI_SIZE,0) + sSep + toString(SCH_SESSION!APP_PARAM_CACHE.CI_TOTAL_SIZE,0), 1)
        EndIf
    EndIf
Until iPos = -1


Return M4_SUCCESS

