M4RCH_RULES3/ID_TI/ROOT_SESSION.SOURCE_CODE:
// =============================================================================
// Checks whether an organization can use a locator or not
//
// Arguments
//    AI_ID_LOCATOR (number): Locator identifier
//	AI_ID_ORGANIZATION (string): Organization identifier
//    AI_CHECK_MODE (number): Check mode
//        1 -> Check if locator is valid for organization
//        2 -> Check if organization is valid for locator
//    AI_M4OBJECT (string): M4Object identifier for traces
//
// Return
//    M4_SUCCESS if pair is valid
//    M4_ERROR otherwise 
// =============================================================================

if AI_ID_LOCATOR = 0 then
    // Locator 0 is valid for all organizations
    return M4_SUCCESS
endif

locator = SESSION_LOCATORS.FindRegister("ID_LOCATOR", AI_ID_LOCATOR, M4_EQUAL)

if locator = -1 then
    SESSION_LOCATORS.AddRegister()
    SESSION_LOCATORS.ID_LOCATOR = AI_ID_LOCATOR
    SESSION_LOCATOR_ORGS.LOAD_BLK()
else
    SESSION_LOCATORS.MoveTo(locator)
endif

if SESSION_LOCATOR_ORGS.Count() = 0 then
    // No such locator
    SetLog(M4_ERRORLOG, 0, 24, 247, ToString(AI_ID_LOCATOR, 0), AI_M4OBJECT)
    return M4_ERROR
endif

if SESSION_LOCATOR_ORGS.BSEARCH(1, AI_ID_ORGANIZATION) = -1 then   
    if AI_CHECK_MODE = 2 then
        // Organization not valid for locator
        SetLog(M4_ERRORLOG, 0, 24, 249, AI_ID_ORGANIZATION, AI_M4OBJECT, ToString(AI_ID_LOCATOR, 0))
    else
        // Locator not valid for organization
        SetLog(M4_ERRORLOG, 0, 24, 248, ToString(AI_ID_LOCATOR, 0), AI_M4OBJECT, AI_ID_ORGANIZATION)
     endif
    return M4_ERROR
endif

