return  iReturn

// Normalizes a number to fit in the range [base, 2^31 - 1]

base = 100000000
divider = 2147483648    // 2^31

return base + Div(AI_NUMBER - base, divider - base)

// =========================================================================
// Calcula si una sociedad debe auditar o no.
// Si la sociedad que se pasa es nula utiliza la actual
// Argumentos
//      ai_sOrganization: Sociedad a chequear
// Resultado
//      1 si está activa la auditoría ó 0 sino lo está
// =========================================================================

// Si no hay ninguna sociedad activa se devuelve que no
if USR_AUDIT_ACTIVE = 0 OR IsNull(USR_AUDIT_ACTIVE) = M4_TRUE then
    return USR_AUDIT_ACTIVE
endif

// Nos posicionamos en el nodo raíz
Begin()

// Nos posicionamos en el nodo de roles
iRegister = APP_ROLE_SESSION.FindRegister( "ID_APP_ROLE", ID_APP_ROLE, M4_EQUAL )

if iRegister  = -1 then
    return 0
endif

APP_ROLE_SESSION.MoveTo( iRegister )

// Nos posicionamos en el nodo de sociedades
if IsNull( ai_sOrganization ) = M4_TRUE OR ai_sOrganization = "" then
    // Si no nos indican sociedad ni disponemos de ella en el canal sesión
    // se audita si al menos uno de las sociedades audita
    if IsNull( ID_ORGANIZATION ) = M4_TRUE OR ID_ORGANIZATION = "" then
        return USR_AUDIT_ACTIVE
    endif
    ai_sOrganization = ID_ORGANIZATION
endif

iRegister = APP_ROLE_ORG.FindRegister( "ID_ORGANIZATION_USED", ai_sOrganization, M4_EQUAL )

if iRegister  = -1 then
    return 0
endif

APP_ROLE_ORG.MoveTo( iRegister )

iResult = APP_ROLE_ORG.USR_AUDIT_ACTIVE

return iResult

// ===============================================================
//
// USR_INF Method in Node Structure ROOT_SESSION
//
// Arguments:  None
//
// 1- Insert values in Tecnical and Funtional parameters
//
// Return:

//    -1 -> Error 
//	 0 if success
//
// ===============================================================


LogPath = GetRegistryValue("SOFTWARE\Meta4\Mind\3.X\Machine","LogonPath")
if LogPath = "" then
    File = "c:/temp/LOGON.log"
else
    File = LogPath + "/LOGON.log"
endif

LogInf = ""
LogInf = GetRegistryValue("SOFTWARE\Meta4\Mind\3.X\Machine","LogonTrace")

if LogInf = "1" then
    ConcatFile(File, "USR_INF inicio ",FALSE)
    ConcatFile(File,TodayNow())
endif

// 1- Insert values in Tecnical and Funtional parameters
ret = USR_INF_TEC()
if ret = -1 then
    return -1
else
    ret = USR_INF_FUN()
    WU_MASK_CONTROL = 0 
    if ret = -1 then
        return -1
    endif
endif

if LogInf = "1" then
    ConcatFile(File, "USR_INF final ",FALSE)
    ConcatFile(File,TodayNow())
endif


RETURN(0)

// ===============================================================
//
// USR_INF_REFRESH Method in Node Structure ROOT_SESSION
//
// Arguments:  None
//
// 1- Insert values in Tecnical and Funtional parameters when the role and/or organization swithes
//
// Return:

//    -1 -> Error 
//	 0 if success
//

// Bug 0270907. Se asegura que SAV_PARAMS de L2 está liberado para que se pueda asignar sin problemas
// el nuevo rol y/o nueva sociedad. Después de realizar el cambio se libera en su ciclo de vida normal
CloseChannel("SAV_PARAMS")

LOAD_LOGON_PARAMS()
USR_INF_FUN()

CloseChannel("SAV_PARAMS")

return (0)

